<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Device\Infrastructure\Driver\Html;

use DateTimeImmutable;
use Psr\Http\Message\ResponseInterface;
use Psr\Http\Message\ServerRequestInterface;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Value\Random;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationRequest;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\OidcFlowContext;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepInput;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\StepResult;
use Civi\Lughauth\Features\Oidc\Authentication\Domain\Exception\LoginException;
use Civi\Lughauth\Features\Oidc\Authentication\Application\AuthenticateUser;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\OidcStepRouter;
use Civi\Lughauth\Features\Oidc\Theme\Application\DecorateHtml;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\HtmlSecurer;
use Civi\Lughauth\Features\Oidc\Authentication\Infrastructure\Driver\Html\Services\OidcCookieManager;
use Civi\Lughauth\Features\Oidc\Client\Domain\ClientData;
use Civi\Lughauth\Features\Oidc\Device\Application\DeviceAuthorizationService;
use Civi\Lughauth\Features\Oidc\Device\Domain\DeviceAuthorization;
use Civi\Lughauth\Features\Oidc\Device\Domain\DeviceAuthorizationStatus;

class DeviceVerificationHtml
{
    public function __construct(
        private readonly Context $context,
        private readonly DeviceAuthorizationService $deviceAuth,
        private readonly AuthenticateUser $authenticator,
        private readonly HtmlSecurer $securer,
        private readonly DecorateHtml $decorator,
        private readonly OidcCookieManager $cookies,
        private readonly OidcStepRouter $router
    ) {
    }

    public function verify(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $userCode = $this->normalizeUserCode((string) ($request->getQueryParams()['user_code'] ?? ''));
        if ($userCode === '') {
            return $this->renderUserCodeForm($request, $response, null);
        }

        $record = $this->deviceAuth->findByUserCode($tenant, $userCode);
        if (!$record) {
            return $this->renderUserCodeForm($request, $response, 'Invalid user code');
        }
        if ($record->isExpired(new DateTimeImmutable())) {
            return $this->renderUserCodeForm($request, $response, 'Expired user code');
        }
        if ($record->status === DeviceAuthorizationStatus::APPROVED) {
            return $this->renderMessage($request, $response, 'Device already approved');
        }
        if ($record->status === DeviceAuthorizationStatus::DENIED) {
            return $this->renderMessage($request, $response, 'Device access denied');
        }

        $flow = $this->buildContext($request, $tenant, $record);
        $authRequest = $this->buildAuthRequest($flow, $record);
        $input = $this->buildStepInput($flow, $request, $authRequest, new ChallengesState(), []);
        return $this->renderStep(null, null, $input, $response, null, $input->challenges);
    }

    public function formVerify(ServerRequestInterface $request, ResponseInterface $response, array $args): ResponseInterface
    {
        $tenant = $args['tenant'];
        $queryCode = $this->normalizeUserCode((string) ($request->getQueryParams()['user_code'] ?? ''));
        $body = (array) ($request->getParsedBody() ?? []);
        if ($queryCode === '') {
            $postCode = $this->normalizeUserCode((string) ($body['user_code'] ?? ''));
            if ($postCode === '') {
                return $this->renderUserCodeForm($request, $response, 'User code is required');
            }
            $url = rtrim($this->context->getBaseUrl(), '/') . '/oauth/openid/' . $tenant . '/device/verify?user_code=' . urlencode($postCode);
            return $response->withStatus(302)->withHeader('Location', $url);
        }

        $record = $this->deviceAuth->findByUserCode($tenant, $queryCode);
        if (!$record) {
            return $this->renderUserCodeForm($request, $response, 'Invalid user code');
        }
        if ($record->isExpired(new DateTimeImmutable())) {
            return $this->renderUserCodeForm($request, $response, 'Expired user code');
        }
        if ($record->status === DeviceAuthorizationStatus::APPROVED) {
            return $this->renderMessage($request, $response, 'Device already approved');
        }
        if ($record->status === DeviceAuthorizationStatus::DENIED) {
            return $this->renderMessage($request, $response, 'Device access denied');
        }

        $flow = $this->buildContext($request, $tenant, $record);
        $clientRequest = $this->buildAuthRequest($flow, $record);
        $state = new ChallengesState();
        if ($flow->preSessionId !== null && $flow->preSessionId !== '') {
            $state = $this->cookies->loadPreSessionChallenges($tenant, $flow->preSessionId);
        }
        $step = $body['step'] ?? null;
        $input = $this->buildStepInput($flow, $request, $clientRequest, $state, $body);

        try {
            $csid = null;
            if (isset($body['csid'])) {
                $csid = $this->securer->verifyToken($body['csid']);
                if ($csid === null) {
                    throw new UnauthorizedException('missing_csid');
                }
            }
            $result = $this->executeStep($input, $response, null, $step, $csid);
            if ($result->type === StepResult::TYPE_PROCEED && $result->authResponse) {
                $approved = $this->deviceAuth->approveByUserCode($tenant, $queryCode, $result->authResponse->asAuthenticationResult());
                if (!$approved) {
                    return $this->renderMessage($request, $response, 'Device approval failed');
                }
                $cookie = $this->cookies->authenticatedSessionCookie(
                    $tenant,
                    $result->authResponse->sessionId,
                    $result->authResponse->sessionExpiration
                );
                return $cookie->attach($this->renderMessage($request, $response, 'Device approved. You can return to the CLI.'));
            }
            if ($result->type === StepResult::TYPE_RENDER && $result->response) {
                $cookie = $this->cookies->storePreSession($flow, $result->challenges);
                return $cookie->attach($result->response);
            }

            throw new UnauthorizedException();
        } catch (LoginException $ex) {
            return $this->renderStep($ex->getMessage(), $ex->auth, $input, $response, null, $ex->challenges ?? $state);
        } catch (UnauthorizedException $ex) {
            return $this->renderStep($ex->getMessage(), null, $input, $response, null, $state);
        }
    }

    private function renderUserCodeForm(ServerRequestInterface $request, ResponseInterface $response, ?string $error): ResponseInterface
    {
        $message = $error !== null && $error !== '' ? '<p class="error">' . $error . '</p>' : '';
        $html = <<<HTML
            <h1>Device login</h1>
            <p>Enter the user code shown in your terminal.</p>
            {$message}
            <form method="POST">
                <label>User code
                    <input type="text" name="user_code" value="" />
                </label>
                <input class="primary-button" type="submit" value="Continue" />
            </form>
            HTML;
        $response->getBody()->write($this->decorator->getFullPage($request, 'Device', $html, 'es'));
        return $response;
    }

    private function renderMessage(ServerRequestInterface $request, ResponseInterface $response, string $message): ResponseInterface
    {
        $html = '<h1>Device login</h1><p>' . $message . '</p>';
        $response->getBody()->write($this->decorator->getFullPage($request, 'Device', $html, 'es'));
        return $response;
    }

    private function buildContext(ServerRequestInterface $request, string $tenant, DeviceAuthorization $record): OidcFlowContext
    {
        $cookies = $request->getCookieParams();
        $acceptLanguage = $request->getHeader('accept-language');
        $baseUrl = $this->context->getBaseUrl();
        $issuer = $baseUrl . '/openid/' . $tenant;
        $nowState = Random::uuid();
        $nowNonce = Random::uuid();

        return new OidcFlowContext(
            tenant: $tenant,
            clientId: $record->clientId,
            redirect: $baseUrl . '/oauth/openid/' . $tenant . '/device/verify',
            scope: $record->scope,
            responseType: '',
            state: $nowState,
            nonce: $nowNonce,
            audiences: $record->audiences,
            prompt: '',
            locale: $acceptLanguage[0] ?? '',
            baseUrl: $baseUrl,
            issuer: $issuer,
            sessionId: $cookies['AUTH_SESSION_ID_' . strtoupper($tenant)] ?? null,
            preSessionId: $cookies['PRE_SESSION_ID'] ?? null
        );
    }

    private function buildAuthRequest(OidcFlowContext $flow, DeviceAuthorization $record): AuthenticationRequest
    {
        $client = new ClientData($record->clientId, [DeviceAuthorizationService::grantType()], false);
        return new AuthenticationRequest(
            client: $client,
            scope: $record->scope,
            redirect: $flow->redirect,
            responseType: $flow->responseType,
            audiences: array_values(array_unique([$record->clientId, ...$record->audiences]))
        );
    }

    private function buildStepInput(
        OidcFlowContext $flow,
        ServerRequestInterface $request,
        AuthenticationRequest $authRequest,
        ChallengesState $state,
        ?array $body
    ): StepInput {
        return new StepInput(
            context: $flow,
            authRequest: $authRequest,
            challenges: $state,
            body: $body ?? [],
            request: $request
        );
    }

    private function renderStep(?string $message, ?AuthenticationResult $error, StepInput $input, ResponseInterface $response, ?string $stepOverride, ?ChallengesState $challengesOverride): ResponseInterface
    {
        $error = $error === null && $message !== null && $message !== ''
            ? new AuthenticationResult(valid: false, errorMessage: $message)
            : $error;
        $step = $error ? null : ($stepOverride ?? ($input->request->getQueryParams()['step'] ?? null));
        if ($challengesOverride !== null) {
            $input = new StepInput(
                context: $input->context,
                authRequest: $input->authRequest,
                challenges: $challengesOverride,
                body: $input->body,
                request: $input->request
            );
        }
        $result = $this->executeStep($input, $response, $error, $step, null);
        if ($result->type !== StepResult::TYPE_RENDER || !$result->response) {
            throw new UnauthorizedException();
        }
        $cookie = $this->cookies->storePreSession($input->context, $result->challenges);
        return $cookie->attach($result->response);
    }

    private function executeStep(
        StepInput $input,
        ResponseInterface $response,
        ?AuthenticationResult $error,
        ?string $step,
        ?string $csid
    ): StepResult {
        $result = $this->router->run($input, $response, $error, $step, $csid);
        if (!$result) {
            throw new UnauthorizedException();
        }
        return $result;
    }

    private function normalizeUserCode(string $userCode): string
    {
        $code = strtoupper(trim($userCode));
        $code = str_replace([' ', '-'], '', $code);
        if (strlen($code) === 8) {
            $code = substr($code, 0, 4) . '-' . substr($code, 4, 4);
        }
        return $code;
    }
}
